      SUBROUTINE ELMPARC---- DECODE A SINGLE PARAMETER NAME FROM A GIVEN ELEMENT TYPEC--------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DBEAM.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DCENT.CIN'      INCLUDE 'DCORR.CIN'      INCLUDE 'DCVTY.CIN'      INCLUDE 'DDRFT.CIN'      INCLUDE 'DHKICK.CIN'      INCLUDE 'DOCT.CIN'      INCLUDE 'DQUAD.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DROT.CIN'      INCLUDE 'DSEXT.CIN'      INCLUDE 'DSOLE.CIN'      INCLUDE 'DSROT.CIN'      INCLUDE 'NELMS.CIN'      INCLUDE 'NPLIN.CIN'      INCLUDE 'NELMEQ.CIN'      INCLUDE 'RNTYPE.CIN'C-----------------------------------------------------------------------C      GO TO ( 100, 200, 300, 400, 500,5000, 700,5000,5000,5000,     1       1100,1200,5000,5000,5000,5000,5000,1800,1900,2000,     2       5000,5000,5000,5000,2500,5000,5000,2800,2800,5000,     3       5000,5000,5000,3400,3500,3500,5000,5000,5000), TYPERCC---- "BEAM" --- INPUT PHASE SPACEC  100 CALL DECPAR(NBEAM,DBEAM,1,NPLIN,1)      GO TO 5000CC---- "ROTATION" --- POLE FACE ROTATIONC  200 CALL DECPAR(NROT,DROT,1,NPLIN,1)      GO TO 5000CC---- "DRIFT" --- DRIFT SPACEC  300 CALL DECPAR(NDRFT,DDRFT,1,NPLIN,1)      GO TO 5000CC---- "BEND" --- BENDING MAGNET WITHOUT FRINGING FIELDSC  400 CALL DECPAR(NBEND,DBEND,1,NPBEND,1)      GO TO 5000CC---- "QUADRUPO" --- QUADRUPOLEC  500 CALL DECPAR(NQUAD,DQUAD,1,NPLIN,1)      GO TO 5000CC---- "CENTROID" -- CENTROID SHIFTC  700 CALL DECPAR(NCENT,DCENT,1,NPLIN,1)      GO TO 5000CC---- "ACCELERATOR" --- ACCELERATOR MATRIXC 1100 CALL DECPAR(NCVTY,DCVTY,1,NPLIN,1)      GO TO 5000CC---- "CORRELATION" --- CORRELATIONS IN BEAM ELLIPSEC 1200 CALL DECPAR(NCORR,DCORR,1,NPLIN,1)      GO TO 5000CC---- "SEXTUPOL" --- SEXTUPOLEC 1800 CALL DECPAR(NSEXT,DSEXT,1,NPLIN,1)      GO TO 5000CC---- "SOLENOID" --- SOLENOIDC 1900 CALL DECPAR(NSOLE,DSOLE,1,NPLIN,1)      GO TO 5000CC---- "SROT" --- ROTATE AROUND LONGITUDINAL AXISC 2000 CALL DECPAR(NSROT,DSROT,1,NPLIN,1)      GO TO 5000CC---- "OCTUPOLE" --- OCTUPOLEC 2500 CALL DECPAR(NOCT,DOCT,1,NPLIN,1)      GO TO 5000CC---- "RBEND" OR "SBEND" --- BENDING MAGNETS WITH FRINGING FIELDSC 2800 CALL DECPAR(NRBND,DRBND,1,NPRBND,1)      GO TO 5000CC---- "PLASMALE" --- PLASMA LENSC 3400 CALL DECPAR(NQUAD,DQUAD,1,NPLIN,1)      GO TO 5000CC---- "HKICK" OR "VKICK" HORIZONTAL AND VERTICAL KICKC 3500 CALL DECPAR(NHKCK,DHKICK,1,NPLIN,1)      GO TO 5000C 5000 CONTINUE      RETURN      END